function validCatalog(items){return Array.isArray(items)&&items.every(item=>item&&['string','number'].includes(typeof item.id)&&typeof item.fa==='string'&&typeof item.en==='string')&&new Set(items.map(item=>String(item.id))).size===items.length;}
function loadScales(refresh=false){return scaleRequest??=api('scales',{refresh}).then(items=>{if(!validCatalog(items))return;scaleCatalog=items.filter(item=>bundledScales.some(row=>row.id===item.id));}).catch(()=>{}).finally(()=>{scaleRequest=null;});}
function loadInstruments(refresh=false){return instrumentRequest??=Promise.all([api('instruments',{refresh}).then(items=>{if(!validCatalog(items))throw Error('Notation service unavailable.');instruments=items;}),loadScales(refresh)]).finally(()=>{instrumentRequest=null;});}
function refreshCatalogs(refresh=true){return loadInstruments(refresh).catch(()=>{});}
function scaleChoices(meta){const items=scaleCatalog.slice();if(meta.scale_type&&!items.some(row=>row.id===meta.scale_type))items.push(bundledScales.find(row=>row.id===meta.scale_type)||{id:meta.scale_type,fa:meta.scale_type,en:meta.scale_type});return [['',''],...items.map(item=>[item.id,item[config.locale]||item.en||item.fa||item.id])];}
function instrumentStaves(id){const item=instruments.find(entry=>String(entry.id)===String(id));if(Array.isArray(item?.staves)&&item.staves.length===2)return M.clone(item.staves);return String(id).toLowerCase()==='piano'?[{clef:'treble'},{clef:'bass'}]:null;}
