function iconButton(action,kind,extra=''){return '<button type="button" data-action="'+action+'" '+extra+'>'+NotationSymbols.icon(kind)+'</button>';}
function musicButton(action,value,extra){return '<button type="button" data-action="'+action+'" '+extra+'>'+NotationSymbols.note(value)+'</button>';}
function updateTempoOptions(){
 const form=document.getElementById('metadata');if(!form)return;
 const raw=form.elements.tempo_unit.value,[unit]=raw.split(':'),bpm=form.elements.bpm.value,control=form.elements.tempo_text,previous=control.value,options=NotationSymbols.tempos(unit,bpm);
 control.disabled=!options.length;control.innerHTML='<option value=""></option>'+options.map(([value,label])=>'<option value="'+h(value)+'" '+(value===previous?'selected':'')+'>'+h(label)+'</option>').join('');
 control.dispatchEvent(new Event('notation-options-change'));const dots=Number(raw.split(':')[1]||0);form.querySelector('.beat-preview').innerHTML=unit?NotationSymbols.note(unit)+'<span class="beat-dots">'+('·'.repeat(dots))+'</span>':'';NotationSymbols.center(form);
}
const pending=new Map();const t=s=>config.locale==='fa'?(fa[s]||s):s;
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(message){const e=document.getElementById('toast');e.textContent=t(message);e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',5000);}
function bridge(action,data={}){return new Promise((resolve,reject)=>{const id=++requestId;const timeout=setTimeout(()=>{pending.delete(id);reject(Error('Connection failed. Your changes are still here.'));},['pdf','download','export'].includes(action)?300000:35000);pending.set(id,{resolve,reject,timeout});SornazNotation.postMessage(JSON.stringify({id,action,...data}));});}
async function api(action,data={}){
 if(config.embedded)return bridge(action,data);
 let path='',method='GET',body;
 if(action==='list')path='?mode='+encodeURIComponent(data.mode)+'&page='+data.page+'&q='+encodeURIComponent(data.query||'');
 if(action==='instruments'||action==='scales')path='/'+action+(data.refresh?'?refresh=1':'');if(action==='practice-save'||action==='practice-cancel'){path='/'+action;method='POST';body=data;}
 if(action==='get')path='/'+data.sheetId;
 if(action==='save'){path=data.sheetId?'/'+data.sheetId:'';method='POST';body=data.payload;}
 if(action==='delete'||action==='bookmark'||action==='upload'){path='/'+data.sheetId+'/'+action;method='POST';body=data.payload||{};}
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);
 try{const response=await fetch(config.api+path,{method,credentials:'same-origin',signal:controller.signal,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-Token':config.csrf},body:body?JSON.stringify(body):undefined});let result=await response.json();if(result.status!==undefined&&result.data)result=result.data;if(!response.ok||result.success!==true)throw Error(result.message||'Notation service unavailable.');return result.data;}catch(e){if(e instanceof TypeError||e.name==='AbortError')throw Error('Connection failed. Your changes are still here.');throw e;}finally{clearTimeout(timer);}
}
function notifyRoute(){if(config.embedded)SornazNotation.postMessage(JSON.stringify({id:0,action:'route',route:state.route,dirty:state.dirty,piano:config.nativePiano?nativePianoState():undefined,toolbar:{practiceDraft:!!config.practiceDraft,editable:!!state.sheet?.editable&&!state.sheet.editorAllSections&&!state.sheet.editorAllParts,canWrite:!!state.sheet?.editable,overview:!!(state.sheet?.editorAllSections||state.sheet?.editorAllParts),uploaded:!!state.sheet?.uploaded,uploadable:!!state.sheet?.id,playing:state.playing,undo:!!state.history.length,redo:!!state.future.length,selectedNotes:state.selectedNotes.size,title:state.sheet?.metadata.title||''},guest:false,guestTop:document.querySelector('.tabs')?.getBoundingClientRect().bottom||0}));}
function theme(){
 document.documentElement.style.setProperty('--font-scale',config.fontScale||1);
 document.documentElement.style.setProperty('--app-font-weight',config.fontWeight||400);
 document.documentElement.style.setProperty('--app-corner-radius',`${Number(config.cornerRadius??4)}px`);
 const family=/^[a-z0-9_-]+$/i.test(config.fontFamily||'')?config.fontFamily:(config.locale==='fa'?'iran_sansx_fa':'iran_sansx_en');
 let font=document.getElementById('notation-theme-font');if(!font){font=document.createElement('style');font.id='notation-theme-font';document.head.append(font);}
 font.textContent=`@font-face{font-family:NotationTheme;src:url('../fonts/${family}/regular.ttf') format('truetype');font-display:swap}`;
 document.body.classList.toggle('dark',!!config.dark);document.body.classList.toggle('writing',state.route==='editor');document.body.classList.toggle('score-overview',!!(state.sheet?.editorAllSections||state.sheet?.editorAllParts));document.body.classList.toggle('native-toolbar',!!config.nativeToolbar);document.body.style.setProperty('--accent',config.accent||'#0065ff');document.body.dir=config.locale==='fa'?'rtl':'ltr';document.documentElement.lang=config.locale;
}
function button(action,label,extra=''){return `<button type="button" data-action="${action}" ${extra}>${h(t(label))}</button>`;}
function head(title){return `<header class="header">${button('back',config.locale==='fa'?'→':'←',`class="icon" aria-label="${h(t('Back'))}"`)}<h1>${h(t(title))}</h1>${!config.embedded?`<div class="web-tools">${button('language',config.locale==='fa'?'EN':'فارسی')}${button('theme','◐',`aria-label="${h(t('Theme'))}"`)}</div>`:''}</header>`;}
function login(){if(config.embedded)SornazNotation.postMessage(JSON.stringify({id:0,action:'login'}));else location.href='/login';}
async function confirmAction(text,destructive=false){const dialog=document.createElement('dialog');dialog.innerHTML=`<p>${h(t(text))}</p><div class="links">${button('no','No')}${button('yes','Yes',destructive?'class="danger"':'class="primary"')}</div>`;document.body.append(dialog);return new Promise(resolve=>{let done=false;const close=v=>{if(done)return;done=true;dialog.close();dialog.remove();resolve(v);};dialog.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='yes')close(true);if(a==='no')close(false);});dialog.addEventListener('cancel',e=>{e.preventDefault();close(false);});dialog.showModal();});}
async function chooseStaffChange(){const dialog=document.createElement('dialog');dialog.innerHTML=`<p>${h(t('The lower-staff notes will be hidden and will not play. Choose how to continue.'))}</p><div class="links">${button('cancel-change','Cancel')}${button('keep-hidden','Keep hidden')}${button('transfer-notes','Transfer notes','class="primary"')}</div>`;document.body.append(dialog);return new Promise(resolve=>{let done=false;const close=value=>{if(done)return;done=true;dialog.close();dialog.remove();resolve(value);};dialog.addEventListener('click',event=>{const action=event.target.closest('[data-action]')?.dataset.action;if(action==='cancel-change')close(null);if(action==='keep-hidden')close('keep');if(action==='transfer-notes')close('transfer');});dialog.addEventListener('cancel',event=>{event.preventDefault();close(null);});dialog.showModal();});}
async function finishPracticeDraft(cancel=false){
 if(!config.practiceDraft)return;if(cancel){if(state.dirty&&!await confirmAction('Discard unsaved changes?'))return;await api('practice-cancel');return;}
 const sheet={metadata:M.clone(state.sheet.metadata),score:{measures:M.trimmedMeasures(state.sheet)}};
 if(!sheet.score.measures.some(b=>b.notes.some(n=>!n.rest))){toast('Enter at least one note before saving.');return;}
 if(sheet.score.measures.length>8||M.staves(sheet.metadata).length!==1||sheet.score.measures.some(b=>b.repeat||b.tempo||b.multiRest||b.clefChanges?.length||b.notes.some(n=>M.staffOf(n)!==1||M.voiceOf(n)!==1||n.pitches?.length||n.graces?.length||n.ornament||n.harmonic||n.tremolo||n.slide||n.octaveShift||n.noteSize==='cue'||['staccato','staccatissimo','fermata','breath','caesura'].includes(n.articulation)))){toast('Use a single melody without chords, ornaments, repeats, tempo/octave changes, cue notes or duration-changing articulations.');return;}
 if(M.timeline(sheet).duration>30){toast('The question must be at most 30 seconds.');return;}
 const target=document.createElement('div');target.style.cssText='position:fixed;left:-20000px;top:0;width:800px';document.body.append(target);let preview;
 try{NotationRenderer.draw(target,sheet,{});const rows=[...target.querySelectorAll('svg')],width=Math.max(...rows.map(n=>n.viewBox.baseVal.width)),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');let y=0;svg.setAttribute('xmlns','http://www.w3.org/2000/svg');
  for(const row of rows){row.querySelectorAll('.note-hit,.notation-preview-note,[class*="notation-active-background"]').forEach(n=>n.remove());const box=row.viewBox.baseVal,scale=width/box.width,g=document.createElementNS(svg.namespaceURI,'g');g.setAttribute('transform','translate(0 '+y+') scale('+scale+') translate(0 '+(-box.y)+')');while(row.firstChild)g.append(row.firstChild);svg.append(g);y+=box.height*scale;}
  svg.setAttribute('viewBox','0 0 '+width+' '+y);svg.setAttribute('width',String(width));svg.setAttribute('height',String(y));preview=new XMLSerializer().serializeToString(svg);
 }finally{target.remove();}
 if(preview.length>120000){toast('The question is too large. Use fewer measures.');return;}
 state.busy=true;notifyRoute();try{await api('practice-save',{payload:{sheet,preview}});state.dirty=false;}catch(error){toast(error.message);}finally{state.busy=false;notifyRoute();}
}
async function back(){const preview=document.querySelector('.notation-print-preview[open]');if(preview){preview.close();return false;}if(config.practiceDraft&&state.route==='editor'&&!state.activeToolSheet&&!document.querySelector('.duration-picker'))return finishPracticeDraft(true);if(state.activeToolSheet){setToolSheet(null);return;}const picker=document.querySelector('.duration-picker');if(picker){picker.dispatchEvent(new Event('cancel',{cancelable:true}));return;}if(state.busy)return;if(state.route==='list'){if(config.embedded)SornazNotation.postMessage(JSON.stringify({id:0,action:'exit'}));else location.href='/';return;}if(state.route==='form'&&state.formFromEditor){if(state.formOrigin)Object.assign(state.sheet,state.formOrigin);state.formOrigin=null;state.route='editor';state.formFromEditor=false;notifyRoute();render();return;}if((!state.sheet.id||state.dirty)&&!await confirmAction(!state.sheet.id?'Have you decided not to write a new sheet?':'Discard unsaved changes?'))return;stop();state.dirty=false;state.route='list';state.sheet=null;notifyRoute();await load();}
async function load(more=false){const seq=++sequence;state.route='list';state.loading=true;state.error='';if(!more){state.page=1;state.items=[];}render();try{const result=await api('list',{mode:state.mode,page:state.page,query:state.searchQuery});if(seq!==sequence)return;state.items=more?[...state.items,...result.items]:result.items;state.more=result.has_more;}catch(e){if(seq!==sequence)return;state.error=e.message;}finally{if(seq===sequence){state.loading=false;render();}}}
async function open(id){if(state.busy)return;state.sectionStartView=false;state.measureSelected=false;state.busy=true;render();try{try{await loadInstruments();}catch(_){}state.sheet=await api('get',{sheetId:id});normalizeLayout(state.sheet);M.prepare(state.sheet);if(!state.sheet.metadata.scale_type&&state.sheet.metadata.key)state.sheet.metadata.scale_type=String(state.sheet.metadata.key).endsWith('m')?'minor':'major';state.sheet.metadata.tempo_dots=Number(state.sheet.metadata.tempo_dots||0);state.lastInsertedDuration=null;state.lastInsertedDots=0;state.selectedNotes.clear();state.route='editor';state.dirty=false;state.bar=0;state.staff=1;state.voice=1;state.tuplet='';state.note=-1;state.chordMode=false;state.chordTone=-1;state.history=[];state.future=[];notifyRoute();}catch(e){toast(e.message);}finally{state.busy=false;render();}}
async function newSheet(){state.sectionStartView=false;state.measureSelected=false;try{await loadInstruments();}catch(e){toast(e.message);return;}state.sheet=M.fresh();state.sheet.editable=true;Object.assign(state.sheet.metadata,{instrument:'',scale_type:'',key:'',tempo_note:'',tempo_dots:0,tempo_text:'',bpm:''});state.choice={duration:'q',accidental:'',dots:0,rest:false,dynamic:'',articulation:'',bow:'',finger:'',ornament:''};state.lastInsertedDuration=null;state.lastInsertedDots=0;state.selectedNotes.clear();state.tuplet='';state.graceMode=false;state.paletteOpen=false;state.activeToolSheet=null;state.formFromEditor=false;state.route='form';state.manualTime=false;state.dirty=false;notifyRoute();render();}
function field(key,label,type='text',attrs=''){if(type==='textarea')return `<label class="field field-wide"><span>${h(t(label))}</span><textarea name="${key}" rows="5" ${attrs}>${h(state.sheet.metadata[key])}</textarea></label>`;return `<label class="field ${key==='title'?'field-wide':''}"><span>${h(t(label))}</span><input name="${key}" type="${type}" ${attrs} value="${h(state.sheet.metadata[key])}"></label>`;}
function select(key,label,options,selected=state.sheet.metadata[key]){return `<label class="field"><span>${h(t(label))}</span><select name="${key}" ${key==='tempo_note'?'class="beat-native" tabindex="-1" aria-hidden="true"':''}>${options.map(o=>{const[value,title]=Array.isArray(o)?o:[o,t(o)];return `<option value="${h(value)}" ${selected===value?'selected':''}>${h(title)}</option>`;}).join('')}</select></label>`;}
Object.assign(fa,{'Manual time':'دستی','Time numerator':'عدد بالای میزان‌نما','Time denominator':'عدد پایین میزان‌نما'});
const standardTimes=[];for(const denominator of [2,4,8,16])for(let numerator=1;numerator<=Math.min(16,denominator*4);numerator++)standardTimes.push(numerator+'/'+denominator);
function timeChoices(){return [['',t('Inherit time')],...standardTimes.map(value=>[value,value]),['manual',t('Manual time')]];}
function clefChoices(){return [['',t('Inherit clef')],...['treble','treble_8vb','treble_8va','bass','alto','tenor','soprano','mezzo-soprano','baritone-f'].map(value=>[value,t(value)])];}
function keyChoices(meta){const values=(M.iranianIntervals?.[meta.scale_type]?(M.iranianTonics||[]).map(([value,fa,en])=>[value,config.locale==='fa'?fa:en]):M.keys.filter(value=>meta.scale_type==='major'?!value.endsWith('m'):meta.scale_type?value.endsWith('m'):true).map(value=>[value,value]));const count=key=>{const iran=M.iranianSignature(meta.scale_type,key);if(iran)return iran.accidentals.reduce((n,a)=>n+(['bk','#o'].includes(a.accidental)?2:1),0);return ({C:0,Am:0,G:1,Em:1,F:1,Dm:1,D:2,Bm:2,Bb:2,Gm:2,A:3,'F#m':3,Eb:3,Cm:3,E:4,'C#m':4,Ab:4,Fm:4,B:5,'G#m':5,Db:5,Bbm:5,'F#':6,'D#m':6,Gb:6,Ebm:6,'C#':7,'A#m':7,Cb:7,Abm:7})[key]||0;};values.sort((a,b)=>count(a[0])-count(b[0]));return [['',t('Inherit key')],...values];}
function timeSignatureForm(meta){const manual=state.manualTime||!!meta.time&&!standardTimes.includes(meta.time),parts=String(meta.time||'4/4').split('/');return {main:select('time','Time Signature',timeChoices(),manual?'manual':meta.time),detail:manual?'<div class="form-row manual-time-row">'+select('time_top','Time numerator',Array.from({length:32},(_,i)=>String(i+1)),parts[0])+select('time_bottom','Time denominator',[1,2,4,8,16,32,64,128,256].map(String),parts[1])+'</div>':''};}
function normalizeFormTime(values,previous='4/4'){const parts=String(previous||'4/4').split('/');if(values.time==='')values.time=previous||'4/4';if(values.time==='manual')values.time=String(values.time_top||parts[0])+'/'+String(values.time_bottom||parts[1]);delete values.time_top;delete values.time_bottom;return values;}
function renderForm(){
  const m=state.sheet.metadata,timeForm=timeSignatureForm(m),text=(key,label)=>field(key,label,'text','maxlength="180" '+(key==='title'?'required':'')),grand=instrumentStaves(m.instrument)?.length===2;
 const catalog=instruments.map(i=>[String(i.id),i[config.locale]||i.fa||i.en]);
 if(m.instrument&&!catalog.some(([id])=>id===m.instrument))catalog.push([m.instrument,t(m.instrument)]);
 const row=(count,content)=>'<div class="form-row columns-'+count+'">'+content+'</div>';
 const scaleType=m.scale_type||'';
 const beatChoices=durationOptions();if(M.durations[m.tempo_note]&&!beatChoices.some(item=>item.duration===m.tempo_note&&item.dots===Number(m.tempo_dots||0)))beatChoices.push({duration:m.tempo_note,dots:Number(m.tempo_dots||0)});
 const beatUnits=beatChoices.map(({duration,dots})=>({duration,dots,value:M.ticks({duration,dots})})).sort((a,b)=>b.value-a.value);
 const selectedBeat=(m.tempo_note||'')+':'+Number(m.tempo_dots||0),beatSelect=`<label class="field beat-field"><span>${h(t('Note type'))}</span><select name="tempo_unit" class="beat-native" tabindex="-1" aria-hidden="true"><option value=""></option>${beatUnits.map(item=>`<option value="${item.duration}:${item.dots}" ${selectedBeat===item.duration+':'+item.dots?'selected':''}>${item.duration}</option>`).join('')}</select><details class="beat-picker"><summary aria-label="${h(t('Note type'))}"><span class="beat-preview">${m.tempo_note?NotationSymbols.note(m.tempo_note)+'<span class="beat-dots">'+('·'.repeat(m.tempo_dots||0))+'</span>':''}</span><span>⌄</span></summary><div class="beat-options">${beatUnits.map(item=>`<button type="button" data-action="beat-unit" data-value="${item.duration}:${item.dots}" aria-label="${h(t('Note type'))}">${NotationSymbols.note(item.duration)}<span class="beat-dots">${'·'.repeat(item.dots)}</span></button>`).join('')}</div></details></label>`;
 return '<section class="shell form">'+head('Notation')+'<form id="metadata">'+
 row(1,text('title','Title'))+
 row(2,text('composer','Composer')+text('arranger','Arranger'))+
 row(2,text('lyricist','Lyricist')+select('instrument','Instrument',[['',''],...catalog]))+
 '<div class="form-row scale-key-row">'+select('scale_type','Scale',scaleChoices(m))+select('key','Key Signature',keyChoices(m).filter(([key])=>key!=='')).replace('<select ','<select '+(scaleType?'':'disabled '))+'</div>'+
  '<div class="form-row clef-time-row">'+(grand?`<label class="field"><span>${h(t('Clef'))}</span><input value="${h(t('Upper staff'))} · ${h(t('Lower staff'))}" readonly></label>`:select('clef','Clef',clefChoices()))+timeForm.main+'</div>'+timeForm.detail+
 '<div class="form-row tempo-row">'+beatSelect+field('bpm','Metronome Mark','text','inputmode="numeric" pattern="[0-9]+" maxlength="3" required')+select('tempo_text','Tempo Text',[['',''],...NotationSymbols.tempos(m.tempo_note,m.bpm)])+'</div>'+
 row(1,field('subtitle','Description','textarea','maxlength="1000"'))+
 '<button class="primary full" type="submit">'+h(t(state.sheet.id?'Save changes':'Start Writing'))+'</button></form></section>';
}
function sheetMenu(s){return `<details class="sheet-menu"><summary aria-label="Menu">⋮</summary><div>${s.editable?button('rename','Rename',`data-id="${s.id}"`):''}${button('add-to-list','Add to list',`data-id="${s.id}"`)}${button('share-sheet','Share',`data-id="${s.id}"`)}${button('musicxml','Export MusicXML',`data-id="${s.id}"`)}${s.editable?button('delete','Delete',`class="danger" data-id="${s.id}"`):''}</div></details>`;}
function selectionBar(){if(!state.selected.size)return'';const rows=state.items.flatMap(s=>s.kind==='list'?(s.items||[]):[s]),all=rows.length>0&&rows.every(s=>state.selected.has(s.id)),selected=rows.filter(s=>state.selected.has(s.id)),allEditable=selected.every(s=>s.editable);return `<div class="selection-bar">${button('select-all',all?'☑':'☐',`class="icon" aria-label="${h(t('Select all'))}"`)}<span>${state.selected.size}</span><span class="selection-spacer"></span><details class="sheet-menu bulk-menu"><summary aria-label="Menu">⋮</summary><div>${state.selected.size===1&&allEditable?button('rename-selected','Rename'):''}${button('add-selected-to-list','Add to list')}${button('share-selected','Share')}${allEditable?button('delete-selected','Delete','class="danger"'):''}</div></details>${button('clear-selection','×',`class="icon" aria-label="${h(t('Cancel'))}"`)}</div>`;}
function renderSheet(s,nested=false){if(s.kind==='list'){const open=state.expanded.has(s.id),title=s.favorite?t('Favorite'):s.title;return `<div class="notation-list-wrap"><article class="sheet notation-list"><span class="list-icon">${s.favorite?'♡':'☷'}</span><button class="open" data-action="toggle-list" data-list="${h(s.id)}"><strong>${h(title)}</strong><small>${Number(s.count)||0} ${config.locale==='fa'?'نت':'scores'}</small></button></article>${open?`<div class="list-contents">${(s.items||[]).map(item=>renderSheet(item,true)).join('')}</div>`:''}</div>`;}const selected=state.selected.has(s.id);return `<article class="sheet ${nested?'nested-sheet':''} ${selected?'selected':''}" data-sheet-id="${s.id}"><button class="open" data-action="open" data-id="${s.id}"><strong>${h(s.title)}</strong><small>${h([s.metadata?.composer,s.metadata?.arranger||s.author].filter(Boolean).join(' – '))}</small></button>${iconButton('pdf-item','pdf',`class="icon" data-id="${s.id}" aria-label="${h(t('PDF'))}"`)}${s.editable&&config.userId?iconButton('upload','upload',`class="icon" data-id="${s.id}" aria-label="${h(t('Upload'))}"`):''}<button type="button" class="icon visibility" data-action="visibility" data-id="${s.id}" ${s.editable?'':'disabled'} aria-label="visibility">${NotationSymbols.icon(s.visibility==='private'?'eye-off':'eye')}</button>${sheetMenu(s)}</article>`;}
