function scaleAllows(name){if(config.pianoLabelMode!==2)return true;if(M.iranianIntervals?.[state.sheet.metadata.scale_type]){const pcs={C:0,'C#':2,D:4,'D#':6,E:8,F:10,'F#':12,G:14,'G#':16,A:18,'A#':20,B:22};return M.iranianSignature?.(state.sheet.metadata.scale_type,state.sheet.metadata.key).degrees.some(d=>(d.quarter%24+24)%24===pcs[name]);}const meta=state.sheet.metadata,type=meta.scale_type||'major',root=String(meta.key||'C').replace(/m$/,''),pc={C:0,'C#':1,Db:1,D:2,'D#':3,Eb:3,E:4,F:5,'F#':6,Gb:6,G:7,'G#':8,Ab:8,A:9,'A#':10,Bb:10,B:11,Cb:11},intervals=type==='harmonic_minor'?[0,2,3,5,7,8,11]:type==='melodic_minor'?[0,2,3,5,7,9,11]:type==='minor'?[0,2,3,5,7,8,10]:[0,2,4,5,7,9,11];return intervals.includes((pc[name]-pc[root]+12)%12);}
Object.assign(fa,{Sori:'سُری',Koron:'کُرُن'});
function showQuarterPiano(){return !!M.iranianIntervals?.[state.sheet?.metadata.scale_type];}
