 const clefs=clefChoices();
 for(let staff=M.staves(state.sheet.metadata).length;staff>=1;staff--)controls.unshift(measureSelect('clef'+staff,staff===1&&M.staves(state.sheet.metadata).length===2?'Upper staff clef':staff===2?'Lower staff clef':'Staff clef',clefs,bar.clefs?.[staff]||''));
