function captureForm(){const form=document.getElementById('metadata');if(state.route==='form'&&form){const values=normalizeFormTime(Object.fromEntries(new FormData(form)),state.sheet.metadata.time);delete values.public;values.bpm=values.bpm===''?'':Number(values.bpm);if(values.tempo_unit){const[unit,dots]=values.tempo_unit.split(':');values.tempo_note=unit;values.tempo_dots=Number(dots);delete values.tempo_unit;}Object.assign(state.sheet.metadata,values);}}
