 const [part,note]=active,target=element.querySelector('[data-part="'+part+'"] [data-bar="'+note.bar+'"][data-note="'+note.note+'"]')||element.querySelector('[data-part="'+part+'"] [data-bar="'+note.bar+'"]');if(!target)return;
 const bounds=element.getBoundingClientRect(),rect=target.getBoundingClientRect(),inset=24;let left=element.scrollLeft;
