function showPlayingMeasure(bar){if(state.sheet?.editorAllParts)return followEnsemblePlayback();const rect=document.querySelector(`#score [data-bar="${bar}"]`);if(!rect)return;const bounds=rect.getBoundingClientRect(),scroller=document.scrollingElement||document.documentElement,top=12,bottom=innerHeight-180;if(bounds.bottom>bottom)scroller.scrollTop+=bounds.bottom-bottom;else if(bounds.top<top)scroller.scrollTop+=bounds.top-top;}
function render(){if(sectionMotion&&!sectionMotion.committing)disposeSectionMotion();sectionSwipe=null;document.querySelector('.duration-picker')?.dispatchEvent(new Event('cancel',{cancelable:true}));root.querySelector('.notation-tool-sheet')?.close();window.NotationControls?.dispose();if(state.route!=='editor')state.activeToolSheet=null;const scroll=document.querySelector('.piano-scroll');if(scroll){const oldQuarter=scroll.dataset.quarterTones==='true',ratio=pianoKeyWidth()/(oldQuarter?pianoStyle().iranianWhiteWidth:pianoStyle().whiteWidth);state.pianoScroll=Math.max(0,(scroll.scrollLeft+scroll.clientWidth/2)*ratio-scroll.clientWidth/2);}theme();document.body.classList.toggle('note-selected',state.route==='editor'&&state.selectedNotes.size>0);root.innerHTML=state.route==='list'?renderList():state.route==='form'?renderForm():renderEditor();mountToolSheet();if(state.busy)root.insertAdjacentHTML('beforeend',`<div class="veil">${h(t('Saving…'))}</div>`);if(state.route==='form'){updateTempoOptions();root.querySelector('[name=instrument]').required=true;}if(state.route==='editor'){draw();const piano=document.querySelector('.piano-scroll');if(piano)piano.scrollLeft=state.pianoScroll??(23*pianoKeyWidth()-piano.clientWidth/2);requestAnimationFrame(()=>{revealActiveSectionTab();if(state.sectionScrollReset){resetSectionViewport();state.sectionScrollReset=false;return;}if(state.playing)showPlayingMeasure(state.playBar<0?state.bar:state.playBar);else if(!state.selectedNotes.size&&!state.sheet.editorAllSections&&!state.sheet.editorAllParts)keepLastMeasureVisible();});}positionEditorOverlays();NotationSymbols.center(root);applyNotationDependencies();window.NotationControls?.decorate(root,{locale:config.locale,showHelp:config.showHelp,scaleType:state.sheet?.metadata.scale_type||''});requestAnimationFrame(notifyRoute);}
