function resetPartSelection(){state.sectionStartView=false;state.measureSelected=false;state.bar=0;state.staff=1;state.voice=1;state.note=-1;state.selectedNotes.clear();state.chordMode=false;state.chordTone=-1;state.graceMode=false;state.tuplet='';state.choice={duration:'q',accidental:'',dots:0,rest:false,dynamic:'',articulation:'',bow:'',finger:'',ornament:''};state.activeToolSheet=null;state.paletteOpen=false;state.measureToolsOpen=false;state.paperScroll=0;state.pianoScroll=null;}
function switchPart(index){if(state.route!=='editor'||state.busy||index===(state.sheet.editorPart||0)&&!state.sheet.editorAllParts)return;stop();activatePart(index);resetPartSelection();notifyRoute();render();}
function addPart(){if(state.route!=='editor'||!state.sheet.editable||state.busy)return;if(config.practiceDraft)return;const all=editorParts();if(all.length>=maxParts)return toast('At most 8 parts.');mutate(()=>{const metadata=M.clone(state.sheet.metadata),measures=state.sheet.score.measures.map(bar=>{const next={notes:[],preserve:true};for(const field of ['time','timeSymbol','length','key','tempo'])if(bar[field]!==undefined)next[field]=M.clone(bar[field]);return next;});const blankSections=editorSections().map((score,index)=>index?{measures:score.measures.map(()=>({notes:[],preserve:true}))}:null).slice(1),fresh={metadata,score:{measures}};if(blankSections.length)fresh.score.sections=blankSections;state.sheet.score.parts=state.sheet.score.parts||[];state.sheet.score.parts.push(fresh);activatePart(all.length);resetPartSelection();},true);}
