 const options=document.createElement('div');options.className='duration-options rest-duration-options';
 let closed=false;const close=()=>{if(closed)return;closed=true;pendingDurationSelection=null;selection.source?.classList.remove('is-pressed');dialog.close();dialog.remove();notifyRoute();if(selection.source?.isConnected&&!config.nativePiano)selection.source.focus({preventScroll:true});};
