  if(rest){item.dataset.restDuration=value.duration;item.dataset.restDots=String(value.dots);}
  item.setAttribute('aria-label',t(rest?'Rest':'Duration')+' '+value.duration+' '+('·'.repeat(value.dots)));item.innerHTML=(rest?NotationSymbols.rest(value.duration):NotationSymbols.note(value.duration))+'<span class="duration-dots">'+('·'.repeat(value.dots))+'</span>';
